      "claim": "Juicebox has grown headcount 83.7% in six months",
      "verdict": "supported",
      "evidence": "company.headcount.growth_percent.6m = 83.72093023255815; signals[headcount_growth].payload.growth_6m_pct = 83.7",
      "reason": "Six-month headcount growth is 83.7% in both the headcount and signal data."
    },
    {
      "claim": "Juicebox headcount is 158",
      "verdict": "supported",
      "evidence": "company.headcount.total = 158",
      "reason": "Total headcount is listed as 158."
    },
    {
      "claim": "Quillpath flags stalled deals nightly",
      "verdict": "contradicted",
      "evidence": "\"Flags stalled deals every morning: no activity, missing next step, or close date slipped.\"",
      "reason": "The product text says stalled deals are flagged every morning, not nightly (it reads the CRM nightly)."
    },
    {
      "claim": "Quillpath sends a weekly forecast summary",
      "verdict": "supported",
      "evidence": "\"Writes a weekly pipeline and forecast summary the founder can forward to the board.\"",
      "reason": "The product produces a weekly forecast summary, though the text says \"writes\" rather than \"sends\"."
    },
    {
      "claim": "The weekly forecast summary can be forwarded to the board",
      "verdict": "supported",
      "evidence": "\"Writes a weekly pipeline and forecast summary the founder can forward to the board.\"",
      "reason": "The product text explicitly says the founder can forward the summary to the board."
    },
    {
      "claim": "Setup takes about 15 minutes",
      "verdict": "supported",
      "evidence": "\"Connects to HubSpot or Salesforce in about 15 minutes (read-only access).\"; \"Setup takes about 15 minutes; no RevOps project needed.\"",
      "reason": "The product text states setup takes about 15 minutes."
    },
    {
      "claim": "Setup works on the prospect's existing CRM",
      "verdict": "supported",
      "evidence": "\"Works on top of the existing CRM; nothing to migrate.\"",
      "reason": "The product works on the existing CRM; the text refers to the team's CRM rather than the prospect's, which is a minor wording difference."
    }
  ]
